// One migration/creation adapter for authored semantic edges and attachments.
const guideMetadata={tee:[{name:'Dobladillo',indices:[0],offset:11}],pants:[{name:'Dobladillo izquierdo',indices:[1],offset:24},{name:'Dobladillo derecho',indices:[0],offset:24}],shorts:[{name:'Dobladillo izquierdo',indices:[1],offset:24},{name:'Dobladillo derecho',indices:[0],offset:24}]};
const attachedNames=new Set(['Cintura','Cintura rib','Cuello','Capucha','Abertura capucha','Costura capucha','Tiro','Presilla','Botón','Bragueta','Bolsillo delantero izquierdo','Bolsillo delantero derecho','Bolsillo trasero','Dibujo bolsillo','Bolsillo canguro','Guía de cordón','Manga izquierda','Manga derecha','Puño izquierdo','Puño derecho','Costura lateral izquierda','Costura lateral derecha','Costura manga izquierda','Costura manga derecha']);
export function bindTemplateGeometry(p){for(const os of Object.values(p.views)){const body=os.find(o=>o.role==='body');if(!body?.semanticEdges?.hem)return;for(const o of os){const guide=(guideMetadata[p.kind]||[]).find(m=>m.name===o.name);if(guide&&o.type==='path'&&!o.closed){const ids=guide.indices.map(i=>body.semanticEdges.hem[i]).filter(Boolean);if(!ids.length)continue;for(const dependent of os.filter(e=>e.source===o.id)){dependent.source=body.id;dependent.edgeIds=ids;dependent.offset=guide.offset-5;delete dependent.mirrorPeer;}o.type='parallel';o.source=body.id;o.edgeIds=ids;o.offset=guide.offset;o.position='inside';o.category='construction';o.semanticType='hemGuide';delete o.nodes;delete o.closed;delete o.mirrorPeer;delete o.symmetry;}else if(o.id!==body.id&&!o.source&&attachedNames.has(o.name))o.attachment??={source:body.id,mode:'affine'};}}return p;}
